// src/i18n/index.ts
var import_obsidian = require("obsidian");
var locales = {
  en: en_default,
  zh: zh_default
};
var I18n = class {
  constructor() {
    this.locale = this.detectLocale();
    this.translations = locales[this.locale] || locales.en;
  }
  /**
   * Detect locale from Obsidian or system
   */
  detectLocale() {
    const obsidianLang = (0, import_obsidian.getLanguage)();
    console.debug("[HybridGitSync] Obsidian language:", obsidianLang);
    if (obsidianLang) {
      if (obsidianLang.startsWith("zh"))
        return "zh";
      if (obsidianLang.startsWith("en"))
        return "en";
    }
    const systemLocale = navigator.language;
    console.debug("[HybridGitSync] System locale (fallback):", systemLocale);
    if (systemLocale.startsWith("zh"))
      return "zh";
    return "en";
  }
  /**
   * Get translated string
   * @param key Translation key
   * @param params Optional parameters for interpolation
   */
  t(key, params) {
    let text = this.translations[key] || key;
    if (params) {
      Object.entries(params).forEach(([paramKey, value]) => {
        text = text.replace(new RegExp(`\\{${paramKey}\\}`, "g"), String(value));
      });
    }
    return text;
  }
  /**
   * Get current locale
   */
  getLocale() {
    return this.locale;
  }
  /**
   * Set locale
   */
  setLocale(locale) {
    this.locale = locale;
    this.translations = locales[locale] || locales.en;
  }
};
var i18nInstance = null;
function initI18n() {
  i18nInstance = new I18n();
  return i18nInstance;
}
function getI18n() {
  if (!i18nInstance) {
    i18nInstance = new I18n();
  }
  return i18nInstance;
}
function t(key, params) {
  return getI18n().t(key, params);
}

