var API_BASE = "https://api.github.com";
var DEBUG = false;
function log(...args) {
  if (DEBUG) {
    console.debug("[OAuth]", ...args);
  }
}
async function requestDeviceCode() {
  const response = await (0, import_obsidian2.requestUrl)({
    url: DEVICE_CODE_URL,
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Accept": "application/json"
    },
    body: JSON.stringify({
      client_id: CLIENT_ID,
      scope: SCOPE
    }),
    throw: false
  });
  if (response.status !== 200) {
    throw new Error(`Failed to request device code: ${response.text}`);
  }
  return response.json;
}
async function pollForAccessToken(deviceCode, interval = 5, maxAttempts = 60) {
  for (let i = 0; i < maxAttempts; i++) {
    await sleep(interval * 1e3);
    log(`Polling attempt ${i + 1}/${maxAttempts}...`);
    const response = await (0, import_obsidian2.requestUrl)({
      url: ACCESS_TOKEN_URL,
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json"
      },
      body: JSON.stringify({
        client_id: CLIENT_ID,
        device_code: deviceCode,
        grant_type: "urn:ietf:params:oauth:grant-type:device_code"
      }),
      throw: false
    });
    log("Response status:", response.status);
    log("Response body:", response.text);
    if (response.status !== 200) {
      log("Non-200 status, continuing...");
      continue;
    }
    const data = response.json;
    log("Parsed response:", data);
    if (data.access_token) {
      log("Got access token!");
      const username = await getUsername(data.access_token);
      return { success: true, token: data.access_token, username };
    }
    if (data.error === "authorization_pending") {
      log("Still pending...");
      continue;
    }
    if (data.error === "slow_down") {
      log("Slowing down...");
      interval += 5;
      continue;
    }
    log("Error:", data.error, data.error_description);
    return { success: false, error: data.error_description || data.error };
  }
  return { success: false, error: "Authorization timed out" };
}
async function getUsername(token) {
  try {
    const response = await (0, import_obsidian2.requestUrl)({
      url: `${API_BASE}/user`,
      headers: { "Authorization": `token ${token}` },
      throw: false
    });
    if (response.status === 200) {
      return response.json.login;
    }
  } catch (e) {
  }
  return void 0;
}
async function listRepos(token) {
  const repos = [];
  let page = 1;
  while (true) {
    const response = await (0, import_obsidian2.requestUrl)({
      url: `${API_BASE}/user/repos?per_page=100&page=${page}&sort=updated`,
      headers: {
        "Authorization": `token ${token}`,
        "Accept": "application/json"
      },
      throw: false
    });
    if (response.status !== 200)
      break;
    const data = response.json;
    if (data.length === 0)
      break;
    for (const repo of data) {
      repos.push({
        fullName: repo.full_name,
        name: repo.name,
        description: repo.description || "",
        private: repo.private,
        defaultBranch: repo.default_branch
      });
    }
    if (data.length < 100)
      break;
    page++;
  }
  return repos;
}
function sleep(ms) {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}

// src/auth/oauth-modal.ts
var import_obsidian3 = require("obsidian");
var OAuthModal = class extends import_obsidian3.Modal {
  // 5 minutes
  constructor(app, userCode, verificationUri) {
    super(app);
    this.secondsLeft = 300;
    this.userCode = userCode;
    this.verificationUri = verificationUri;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    contentEl.createEl("h2", { text: t("oauth.title") });
    contentEl.createEl("p", { text: t("oauth.step1") });
    const codeEl = contentEl.createDiv("oauth-code");
    codeEl.createSpan({ text: this.userCode, cls: "oauth-code-text" });
    const copyRow = contentEl.createDiv("oauth-copy-row");
    const copyBtn = copyRow.createEl("button", { text: t("oauth.copyCode") });
    copyBtn.addEventListener("click", () => {
      void navigator.clipboard.writeText(this.userCode).then(() => {
        copyBtn.setText(t("oauth.copied"));
        window.setTimeout(() => copyBtn.setText(t("oauth.copyCode")), 2e3);
      });
    });
    contentEl.createEl("p", { text: t("oauth.step2") });
    contentEl.createEl("a", {
      text: this.verificationUri,
      href: this.verificationUri,
      cls: "oauth-link"
    });
    const btnRow = contentEl.createDiv("oauth-buttons");
    const openBtn = btnRow.createEl("button", { text: t("oauth.openBrowser") });
    openBtn.classList.add("mod-cta");
    openBtn.addEventListener("click", () => {
      window.open(this.verificationUri, "_blank");
    });
    this.timerEl = contentEl.createDiv("oauth-timer");
    this.updateTimer();
    const interval = window.setInterval(() => {
      this.secondsLeft--;
      this.updateTimer();
      if (this.secondsLeft <= 0) {
        window.clearInterval(interval);
        this.close();
      }
    }, 1e3);
    const cancelRow = contentEl.createDiv("oauth-cancel-row");
    const cancelBtn = cancelRow.createEl("button", { text: t("oauth.cancel") });
    cancelBtn.addEventListener("click", () => {
      window.clearInterval(interval);
      this.close();
    });
  }
  updateTimer() {
    const minutes = Math.floor(this.secondsLeft / 60);
    const seconds = this.secondsLeft % 60;
    this.timerEl.setText(t("oauth.expiresIn", {
      time: `${minutes}:${seconds.toString().padStart(2, "0")}`
    }));
  }
  onClose() {
    const { contentEl } = this;
    contentEl.empty();
  }
};

// src/utils/gitignore.ts
var GitignoreRules = class {
  /**
   * @param configDir Obsidian's config folder name (vault.configDir),
   *   not hardcoded to ".obsidian" since users can customize it.
   */
  constructor(configDir) {
    this.patterns = [];
    this.configDir = configDir;
    this.builtInPatterns = [
      `${configDir}/`,
      ".trash/",
      ".git/",
      ".DS_Store",
      "Thumbs.db",
      "*.tmp",
      "*.bak"
    ];
  }
  /**
   * Parse and add patterns from .gitignore content
   */
  addRules(content) {
    const lines = content.split("\n");
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith("#")) {
        this.addPattern(trimmed);
      }
    }
  }
  /**
   * Use built-in patterns as fallback
   */
  useBuiltInPatterns() {
    this.builtInPatterns.forEach((p) => this.addPattern(p));
  }
  /**
   * Get default .gitignore content with localized comments
   */
  getDefaultContent() {
    const dir = this.configDir;
    return `# ${t("gitignore.ignoreDotfiles")}
.*

# ${t("gitignore.keepDotfiles")}
!${dir}/
!.gitignore
!.gitattributes

# ${t("gitignore.obsidianDeviceFiles")}
${dir}/workspace.json
${dir}/workspace-mobile.json

# ${t("gitignore.pluginsDirectory")}
${dir}/plugins/

# ${t("gitignore.cache")}
${dir}/cache/

# ${t("gitignore.trash")}
.trash/

# ${t("gitignore.osFiles")}
.DS_Store
Thumbs.db

# ${t("gitignore.tempFiles")}
*.tmp
*.bak
*.swp
*.swo
*~
`;
  }
  /**
   * Add a single pattern
   */
  addPattern(pattern) {
    let negate = false;
    let cleanPattern = pattern;
    if (cleanPattern.startsWith("!")) {
      negate = true;
      cleanPattern = cleanPattern.substring(1);
    }
    const regex = this.patternToRegex(cleanPattern);
    this.patterns.push({ pattern: cleanPattern, regex, negate });
  }
  /**
   * Check if a path should be ignored
   */
  shouldIgnore(path) {
    let ignored = false;
    for (const p of this.patterns) {
      if (p.regex.test(path)) {
        ignored = !p.negate;
      }
    }
    return ignored;
  }
  /**
   * Filter a list of paths, removing ignored ones
   */
  filter(paths) {
    return paths.filter((p) => !this.shouldIgnore(p));
  }
  /**
   * Convert gitignore pattern to RegExp
   *
   * Git rules:
   * - Pattern without "/" matches basename at any level (e.g. *.tmp matches a/b.tmp)
   * - Pattern with "/" matches from root (e.g. a/b only matches a/b at root)
   * - "**" prefix matches any directory prefix
   */
  patternToRegex(pattern) {
    let regexStr = "";
    let i = 0;
    const dirOnly = pattern.endsWith("/");
    if (dirOnly) {
      pattern = pattern.slice(0, -1);
    }
    const hasSlash = pattern.includes("/");
    if (hasSlash) {
      regexStr += "^";
    } else {
      regexStr += "(^|/)";
    }
    while (i < pattern.length) {
      const char = pattern[i];
      if (char === "*") {
        if (pattern[i + 1] === "*") {
          if (pattern[i + 2] === "/") {
            regexStr += "(.*/)?";
            i += 3;
          } else {
            regexStr += ".*";
            i += 2;
          }
        } else {
          regexStr += "[^/]*";
          i++;
        }
      } else if (char === "?") {
        regexStr += "[^/]";
        i++;
      } else if (char === "[") {
        const end = pattern.indexOf("]", i + 1);
        if (end > -1) {
          regexStr += pattern.substring(i, end + 1);
          i = end + 1;
        } else {
          regexStr += "\\[";
          i++;
        }
      } else {
        if (/[.+^${}()|\\]/.test(char)) {
          regexStr += "\\";
        }
        regexStr += char;
        i++;
      }
    }
    if (dirOnly) {
      regexStr += "(/.*)?$";
    } else {
      regexStr += "(/.*)?$";
    }
    return new RegExp(regexStr);
  }
};
var GITATTRIBUTES_UNIGNORE_RE = /^[ \t]*![ \t]*\/?\.gitattributes[ \t]*$/m;
async function ensureGitAttributesUnignored(vault) {
  let content = null;
  try {
    content = await vault.adapter.read(".gitignore");
  } catch (e) {
    content = null;
  }
  if (content === null) {
    const dir = vault.configDir;
    const fallback = new GitignoreRules(dir).getDefaultContent();
    await vault.adapter.write(".gitignore", fallback);
    return true;
  }
  const normalized = content.replace(/\r\n/g, "\n");
  if (GITATTRIBUTES_UNIGNORE_RE.test(normalized)) {
    return false;
  }
  const prefix = normalized.endsWith("\n") || normalized.length === 0 ? "" : "\n";
  await vault.adapter.write(".gitignore", `${normalized}${prefix}!.gitattributes
`);
  return true;
}

// src/settings.ts
var ConfirmModal = class extends import_obsidian4.Modal {
  constructor(app, title, message, actions) {
    super(app);
    this.resolveFn = null;
    this.title = title;
    this.message = message;
    this.actions = actions;
  }
  /**
   * Open the modal and resolve with the chosen action (null when dismissed).
   * Named differently from Modal#open (which returns void) to avoid overriding
   * the base method's void contract.
   */
  openAndWait() {
    if (this.resolveFn)
      return Promise.resolve(null);
    return new Promise((resolve) => {
      this.resolveFn = resolve;
      super.open();
    });
  }
  settle(value) {
    if (this.resolveFn) {
      const resolve = this.resolveFn;
      this.resolveFn = null;
      resolve(value);
    }
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    contentEl.createEl("h2", { text: this.title });
    for (const line of this.message.split("\n")) {
      contentEl.createEl("p", { text: line });
    }
    const buttonEl = contentEl.createDiv("hgs-confirm-actions");
    for (const action of this.actions) {
      const btn = buttonEl.createEl("button", { text: action.text });
      if (action.warning)
        btn.addClass("mod-warning");
      btn.onclick = () => {
        this.settle(action.value);
        this.close();
      };
      if (action.hint) {
        buttonEl.createDiv({
          text: action.hint,
          cls: "setting-item-description"
        });
      }
    }
    const cancelBtn = buttonEl.createEl("button");
    cancelBtn.textContent = t("ui.cancel");
    cancelBtn.onclick = () => this.close();
  }
  onClose() {
    this.settle(null);
    const { contentEl } = this;
    contentEl.empty();
  }
};
